package org.apache.commons.csv;

import java.io.*;
import java.io.Closeable;
import java.io.Flushable;
import java.io.IOException;
import java.io.StringWriter;
import java.math.*;
import java.sql.ResultSet;
import java.sql.ResultSetMetaData;
import java.sql.SQLException;
import java.util.*;
import org.junit.*;
import org.junit.Before;
import org.junit.Test;
import static org.junit.Assert.*;
import static org.junit.Assert.assertEquals;
import static org.mockito.Mockito.mock;
import static org.mockito.Mockito.when;

public class CSVPrinter_printRecords_TriageGen0Test {

    private StringWriter out;
    private CSVPrinter csvPrinter;

    @Before
    public void setUp() throws IOException {
        out = new StringWriter();
        csvPrinter = new CSVPrinter(out, CSVFormat.DEFAULT);
    }



    @Test
    public void testPrintRecords_SingleRowMultipleColumns() throws SQLException, IOException {
        ResultSet resultSet = mock(ResultSet.class);
        ResultSetMetaData metaData = mock(ResultSetMetaData.class);

        when(resultSet.getMetaData()).thenReturn(metaData);
        when(metaData.getColumnCount()).thenReturn(2);

        // First row: next() returns true, then false
        when(resultSet.next()).thenReturn(true, false);
        // Column values
        when(resultSet.getString(1)).thenReturn("val1");
        when(resultSet.getString(2)).thenReturn("val2");

        csvPrinter.printRecords(resultSet);

        // CSVFormat.DEFAULT uses comma as delimiter and \r\n or \n as line terminator
        // The logic in the method calls print(val) and then println()
        // print(val) for "val1" -> "val1"
        // print(val) for "val2" -> "val2"
        // println() -> "\r\n" (on Windows) or "\n" (on Unix)
        // Note: CSVPrinter.print wraps values in quotes if needed, but for simple strings it's just the string.
        // However, the source method calls print(resultSet.getString(i)) directly.
        // Since CSVPrinter.print(Object) is used, it will follow CSV format rules.

        String expected = "val1,val2" + System.lineSeparator();
        assertEquals(expected, out.toString());
    }










}

